/* EDUTOPIA: a browser-local learning journey. No accounts or credentials in client code. */
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={reflections:{},sources:[],name:'',avatar:0,screen:'home',seen:[],market:false,sorting:false,sortValues:['','',''],sortChecked:false,answers:{},assessment:{},project:Array(6).fill(''),projectSaved:false,researchVisited:false,completed:false};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('edutopia-v1')||'{}')}}catch{state={...defaults}}
let curriculumSource='local demo data',curriculumData=null;
let screen='home',modal=null,observation=-1,sortError=false,chat=[],research={category:'research',query:'Addis Ababa waste separation and collection research',results:[],status:'idle',mode:'',error:''};
let persistence=true,travelTimer,toastTimer;
function save(){try{localStorage.setItem('edutopia-v1',JSON.stringify(state))}catch{persistence=false;toast('Browser storage is unavailable. Keep this tab open and download your notes.')}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200)}
const avatars=[{name:'The Naturalist',skin:'#a96e43',shirt:'#587a53',hair:'#2c3027',hat:'#d0ad6c'},{name:'The Inventor',skin:'#cc9665',shirt:'#a46257',hair:'#342b28',hat:'#a86853'},{name:'The Wayfinder',skin:'#6b4432',shirt:'#487b82',hair:'#292a23',hat:'#d4b982'},{name:'The Storyteller',skin:'#e3b28b',shirt:'#a68c46',hair:'#613f2d',hat:'#75815c'}];
function avatar(i=state.avatar,extra=''){const a=avatars[i]||avatars[0];return `<svg class="avatar-svg ${extra}" viewBox="0 0 100 120" aria-label="${a.name}" role="img"><ellipse cx="50" cy="112" rx="27" ry="5" fill="#253d3322"/><path d="M34 83l-4 28h14l7-25 6 25h14l-6-29" fill="#3b4b3d"/><path d="M28 57q22-18 44 0l6 34H23z" fill="${a.shirt}"/><path d="M28 63l-10 24 9 5 11-23m32-6 11 24-9 5-12-24" fill="${a.shirt}"/><path d="M20 87l-2 9 8 1 2-8m45 0 1 8 8-1-2-9" fill="${a.skin}"/><path d="M35 36q-5-22 15-24 22 1 17 25v15H34" fill="${a.hair}"/><ellipse cx="50" cy="38" rx="17" ry="21" fill="${a.skin}"/><path d="M34 29q1-17 17-16 18 0 17 18l-12-9-7 7-5-5z" fill="${a.hair}"/><path d="M27 25q23-11 46 0v6H27z" fill="${a.hat}"/><path d="M36 24l3-16q13-6 24 1l4 16" fill="${a.hat}"/><path d="M37 18h27v6H37z" fill="#7b603e"/><circle cx="44" cy="38" r="1.5" fill="#302c25"/><circle cx="57" cy="38" r="1.5" fill="#302c25"/><path d="M46 48q5 4 10-1" stroke="#633b2c" fill="none" stroke-width="1.5"/><path d="M37 58l24 30" stroke="#c5aa71" stroke-width="6"/><path d="M54 76h17v20H54z" fill="#b29b68" stroke="#8b784e"/><path d="M54 79h17" stroke="#d8c38f"/><path d="M30 109h15v6H28m29-6h14l3 6H57" fill="#4d3d2e"/></svg>`}
function compass(cls='logo-compass'){return `<svg class="${cls}" viewBox="0 0 100 100" fill="none" aria-hidden="true"><circle cx="50" cy="50" r="38" stroke="currentColor" opacity=".65"/><circle cx="50" cy="50" r="30" stroke="currentColor" opacity=".3"/><path d="M50 2l8 40 40 8-40 8-8 40-8-40L2 50l40-8z" fill="currentColor" opacity=".9"/><path d="M50 14v36H14l29-7zm0 72V50h36L57 57z" fill="#e1c18a"/><path d="M20 20l30 21 30-21-21 30 21 30-30-21-30 21 21-30z" stroke="currentColor" opacity=".5"/><circle cx="50" cy="50" r="5" fill="#c79f5d"/></svg>`}
function owl(){return portrait()}
function header(home=false){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Edutopia world globe">${compass()}<span><span class="brand-name">EDUTOPIA</span><small>THE WORLD IS YOUR CLASSROOM</small></span></button><nav class="nav" aria-label="Main navigation"><button class="nav-link ${screen==='home'?'active':''}" data-action="home">The world</button><button class="nav-link" data-action="adventures">Adventures</button><button class="nav-link" data-action="journal">Field journal</button><button class="nav-pill" data-action="${state.name?'profile':'start'}">${state.name?`<span class="mini-avatar">${avatar()}</span>${esc(state.name)}`:'✧ &nbsp; Explorer’s edition'}</button></nav></header>`}
function footer(){return `<footer class="bottom-bar"><span>EDUTOPIA · A little curiosity. A world of possibility.</span><span>Curriculum: ${esc(curriculumSource)} &nbsp; · &nbsp; <button data-action="about">About this chapter</button> &nbsp; · &nbsp; <button data-action="scene">3D scene</button></span></footer>`}
function button(label,action,disabled=false,kind='primary'){return `<button class="${kind}" data-action="${action}" ${disabled?'disabled':''}>${label}${kind==='primary'?'<span class="arrow">↗</span>':''}</button>`}
function heading(kicker,title,sub,badge=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${badge?`<span class="badge">${badge}</span>`:''}</div>`}
function skills(){return `<div class="skill-tags">${(curriculumData?.skills?.map(s=>s.title)||['Systems thinking','Environmental literacy','Critical thinking','Research','Project planning']).map(s=>`<span>${s}</span>`).join('')}</div>`}
function globe(){return `<div class="globe-scene"><span class="coordinate">9.03° N &nbsp; 38.75° E</span><div class="orbit"></div><div class="globe"><canvas class="earth-canvas" aria-label="Rotating Earth with satellite imagery"></canvas></div><div class="globe-stand"></div><div class="globe-tag"><span>Your first destination</span>↗ &nbsp; Addis Ababa, Ethiopia</div></div>`}
function home(){return `<main id="main"><section class="hero"><div class="hero-copy fade-in"><h1>A world full of <em>possibilities</em></h1><p class="intro">Start with something you wonder about. Explore a place with Atlas, question what you find, and design a project you could try in your own community.</p><div class="hero-actions">${button(state.name?'Continue Your Adventure':'Begin Your Adventure','start')}${state.name?button('Meet your explorer','profile',false,'secondary'):''}</div><div class="under-cta">No account needed <span>·</span> Your adventure, at your pace</div></div>${globe()}</section><div class="hero-foot"><div class="footer-note">${compass('logo-compass')} <span>A LIVING ATLAS OF IDEAS</span></div><div class="footer-note">EXPLORE <span>—</span> QUESTION <span>—</span> CREATE</div><div class="footer-note">ONE PLANET. <strong>ENDLESS DISCOVERIES.</strong></div></div><section class="journey-preview"><div class="chapter-stamp">01</div><div class="preview-copy"><small>THE FIRST CHAPTER &nbsp; / &nbsp; SDG 12</small><h3>Small changes. A city of possibilities.</h3><p>Addis Ababa, Ethiopia &nbsp; · &nbsp; Responsible consumption & production</p></div><button class="text-link" data-action="preview">Discover the adventure <span class="arrow">↗</span></button></section></main>`}
function profile(){return `<main id="main" class="paper-main fade-in"><button class="back" data-action="home">← Back to the world</button>${heading('Every adventure begins with you','Meet your explorer.','A name, a little personality, and a healthy sense of wonder.','01 / Your explorer')}<div class="split"><section class="paper-card"><label for="explorer-name" class="label">What should Atlas call you?</label><input id="explorer-name" maxlength="30" value="${esc(state.name)}" placeholder="Your explorer name" autocomplete="nickname"><p class="form-error" id="name-error"></p><div class="label">Choose your travel companion</div><div class="avatar-options">${avatars.map((a,i)=>`<button class="avatar-option ${state.avatar===i?'selected':''}" data-avatar="${i}" aria-pressed="${state.avatar===i}">${avatar(i)}<span>${a.name}</span></button>`).join('')}</div>${button('Find My Adventure','save-profile')}<p class="hint">Your name, explorer, and progress stay in this browser.</p></section><aside class="paper-card"><div class="portrait-wrap big-avatar">${avatar()}</div><div class="portrait-caption"><h3 id="explorer-preview">${esc(state.name)||'A curious new explorer'}</h3><p>${avatars[state.avatar].name} &nbsp; · &nbsp; Ready for the unknown</p></div></aside></div></main>`}
const goals=[{n:2,title:'Zero Hunger',symbol:'♧',color:'#aa904e',desc:'Explore the future of food.'},{n:4,title:'Quality Education',symbol:'▤',color:'#a76b63',desc:'Open doors through learning.'},{n:6,title:'Clean Water & Sanitation',symbol:'♧',color:'#5798a1',desc:'Follow the journey of water.'},{n:11,title:'Sustainable Cities',symbol:'⌂',color:'#c28b54',desc:'Imagine a city for everyone.'},{n:12,title:'Responsible Consumption',symbol:'∞',color:'#ddbd78',desc:'Addis Ababa · Chapter 01'},{n:13,title:'Climate Action',symbol:'❋',color:'#718a5d',desc:'Discover a changing planet.'}];
function adventures(){return `<main id="main" class="paper-main fade-in"><button class="back" data-action="profile">← Your explorer</button>${heading('Big questions. Real places.','Where will curiosity take you?','Choose a global goal and discover the world through a different lens.','UN Sustainable Development Goals')}<div class="sdg-board">${goals.map(g=>`<button class="sdg ${g.n===12?'playable':''}" style="--accent:${g.color}" data-goal="${g.n}"><span class="sdg-number">${String(g.n).padStart(2,'0')}</span><span class="sdg-symbol">${g.symbol}</span><h3>${g.title}</h3><div class="sdg-bottom"><small>${g.n===12?'PLAY CHAPTER 01 ↗':'COMING SOON'}</small><span>→</span></div><small>${g.desc}</small></button>`).join('')}</div><p class="hint">Our atlas is growing. SDG 12 is the first fully playable chapter; other journeys are future previews.</p></main>`}
function planner(){return `<main id="main" class="paper-main fade-in"><button class="back" data-action="adventures">← All adventures</button>${heading('Your journey, thoughtfully mapped','A small change starts<br>with a good question.','Chapter 01 · Addis Ababa, Ethiopia · SDG 12','Atlas field guide')}<div class="split"><section class="paper-card"><div class="atlas-row">${owl()}<div><div class="section-label">Atlas · Your learning companion</div><p class="atlas-message">Welcome, ${esc(state.name)}. Ready to look at a city a little differently?</p></div></div><p style="font-size:12px;line-height:1.9;margin-top:20px">Welcome, Explorer! Your first mission takes us to Addis Ababa, Ethiopia. Today, we're investigating an important question: how can a growing city improve waste separation and collection? We'll explore two locations, investigate the causes of the challenge, and develop a practical idea for improvement.</p>${guidePanel('planner')}<ol class="plan-list">${['Introduction to the issue','Stop One — Neighborhood Market','Stop Two — Community Sorting Station','Knowledge Assessment','Solutions Laboratory','Research and Project Reflection'].map((s,i)=>`<li><div>${s}<span>${['Look beyond the bin','Discover how waste begins','Connect the whole system','Bring the ideas together','Design a practical pilot','Follow the evidence'][i]}</span></div></li>`).join('')}</ol></section><aside class="journal-aside"><div class="section-label">The question that guides us</div><h3>What happens after<br>we throw it away?</h3><p>Explore how prevention, separation, collection, and processing connect. Then design one improvement you could test.</p><div class="section-label" style="margin-top:28px">Skills for your journey</div>${skills()}<p style="margin-top:22px">Ask Atlas about something you notice. Each reply identifies its source.</p>${button('Begin Journey','travel')}<p class="art-note" style="margin-top:16px">About 15–25 minutes · No time limit<br>Fictional learning locations · Local curriculum data</p></aside></div></main>`}
function travel(){return `<main id="main" class="flight"><div class="flight-city"></div><div class="flight-view"><div class="globe"><canvas class="earth-canvas" aria-label="Earth turns toward Ethiopia"></canvas><span class="flight-pin"></span></div></div><div class="flight-caption"><div class="eyebrow">Destination · East Africa</div><h2>Flying to Addis Ababa</h2><p>Ethiopia · 9.03° N, 38.75° E</p>${button('Enter the city now','map')}</div></main>`}

const countStops=()=>Number(state.market)+Number(state.sorting);
const assessmentPassed=()=>[0,1,2].every(i=>state.assessment[i]===questions[i].correct);
function map(){let n=countStops();return `<main id="main" class="map-layout fade-in"><div class="city-map"></div><div class="map-top"><button class="back" style="margin-bottom:10px" data-action="adventures">← All adventures</button><div class="eyebrow">Ethiopia · Chapter one</div><h1 class="map-title">Addis Ababa</h1><div class="map-subtitle">A city of possibility. A system to discover.</div><div class="map-chapter">∞ &nbsp; SDG 12 &nbsp; / &nbsp; Responsible consumption & production</div></div><aside class="map-panel"><div><h3>Your field journal</h3><p>${n} of 2 places explored</p></div><div class="progress-track"><span style="width:${n*50}%"></span></div>${['Neighborhood Market','Community Sorting Station'].map((x,i)=>`<div class="quest-row ${state[i?'sorting':'market']?'done':''}"><span class="quest-check">${state[i?'sorting':'market']?'✓':i+1}</span>${x}</div>`).join('')}${button(n===2?'Check Your Knowledge':'Explore both locations',n===2?'assessment':'map',n<2)}<button class="inline-link" style="margin-top:12px" data-action="journal">Open saved field notes</button></aside><button class="location market ${state.market?'completed':''}" data-location="market"><span class="marker"><span>♧</span></span><strong>Neighborhood Market</strong><small>${state.market?'✓ EXPLORED':'01 · DISCOVER & INVESTIGATE'}</small></button><button class="location sorting ${state.sorting?'completed':''}" data-location="sorting"><span class="marker"><span>♻</span></span><strong>Community Sorting Station</strong><small>${state.sorting?'✓ EXPLORED':'02 · SORT & CONNECT'}</small></button><div class="map-avatar">${avatar()}<span>${esc(state.name)}</span></div><div class="map-atlas">${owl()}<div><small>ATLAS · GUIDED DEMO COMPANION</small><p class="atlas-message">${n===0?'Every object has a story. Choose a place and let’s follow the trail.':n===1?'One discovery leads to another. Explore the other stop to see the whole system.':'You’ve connected the pieces. Ready to put your discoveries to the test?'}</p><button class="inline-link" data-action="atlas">Ask Atlas ↗</button></div></div>${compass('map-compass')}<p class="map-disclaimer">Illustrated educational simulation · Not a precise geographic map</p></main>`}
const objects=[{icon:'🥬',title:'Food scraps',body:'Peels and spoiled produce form an organic waste stream. Prevent edible food waste first; suitable scraps may have a composting pathway if collection and processing exist.'},{icon:'📦',title:'Single-use packaging',body:'Packaging decisions influence how much waste is created. Avoiding unnecessary single-use wrapping prevents waste before a collection system has to manage it.'},{icon:'🧺',title:'Reusable containers',body:'Durable containers can replace repeated disposable packaging. Reuse needs suitable cleaning and repeated use; prevention comes before recycling or disposal.'}];
const stopQuestions={market:{q:'Which action is most directly an example of waste prevention?',options:['Mixing all materials into one bin.','Reducing unnecessary single-use packaging.','Sending all waste to landfill.'],correct:1,explanation:'Reducing unnecessary packaging avoids creating waste in the first place. Sorting and disposal manage material after it has already become waste.'},sorting:{q:'Why might separate bins fail to solve a city’s waste-management problem by themselves?',options:['Collection systems and processing facilities are also required.','Waste stops existing once it is sorted.','Community participation never matters.'],correct:0,explanation:'Bins are only one link. Reliable collection, safe processing, viable markets or uses for recovered material, and community participation must work together.'}};
const questions=[{q:'Which choice prevents waste at its source?',options:['Use a refillable container repeatedly.','Add another landfill bin.','Sort disposable wrappers after use.'],correct:0,explanation:'A refillable container can avoid repeated disposable packaging. Prevention reduces what is created; sorting handles what already exists.'},{q:'Separated food scraps are collected, then mixed with residual waste. What needs attention?',options:['Only the color of the bins.','The collection and processing pathway.','No further action is needed.'],correct:1,explanation:'Separation needs to be maintained through collection and delivery to an appropriate processing route. The entire chain matters.'},{q:'Which pilot has a measurable success indicator?',options:['Tell everyone to care more.','Make waste disappear someday.','Track weekly participating vendors and kilograms of separated scraps for four weeks.'],correct:2,explanation:'A defined group, timeframe, and repeated measures make the pilot testable. A baseline and contamination checks would strengthen it further.'}];
function quiz(q,key,assessment=false){let selected=assessment?state.assessment[key]:state.answers[key];return `<section class="quiz-block"><h3>${q.q}</h3>${q.options.map((x,i)=>`<button class="option ${selected===i?(i===q.correct?'correct':'incorrect'):''}" data-quiz="${key}" data-answer="${i}" ${assessment?'data-assessment="true"':''}><span class="letter">${String.fromCharCode(65+i)}</span>${x}${selected===i?(i===q.correct?' ✓':' ↻'):''}</button>`).join('')}${selected!==undefined?`<div class="feedback ${selected!==q.correct?'error':''}" role="status"><strong>${selected===q.correct?'Good connection.':'Let’s look again.'}</strong> ${q.explanation}${selected!==q.correct?' Try another answer.':''}</div>`:''}</section>`}
function activity(kind){let isMarket=kind==='market';return `<main id="main" class="paper-main fade-in"><button class="back" data-action="map">← Return to the city map</button>${heading(isMarket?'Stop one · Discover & investigate':'Stop two · Sort & connect',isMarket?'Before the bin.':'Beyond the bin.',isMarket?'Look closer at an everyday market. Where does waste begin?':'A useful system connects people, collection, and processing.',state[kind]?'✓ Location complete':'Educational simulation')}${guidePanel(kind)}<div class="split"><section class="paper-card">${isMarket?`<div class="section-label">Inspect all three objects · ${state.seen.length}/3 discovered</div><div class="object-grid">${objects.map((o,i)=>`<button class="object-card ${state.seen.includes(i)?'seen':''}" data-object="${i}"><span class="object-icon">${fieldSticker(i)}</span><strong>${o.title}</strong></button>`).join('')}</div><div class="observation" aria-live="polite">${observation>=0?`<strong>${objects[observation].title}</strong>${objects[observation].body}`:'Choose an object to uncover its story. Your observations will be added to your field journal.'}</div>${state.seen.length===3?quiz(stopQuestions.market,'market'):'<p class="lock-note">✧ Inspect every object to unlock your question.</p>'}`:`<div class="section-label">Match each example with a pathway</div><p style="font-size:12px">Use these local teaching assumptions: a partner accepts clean rigid bottles and an authorized facility accepts food scraps. Actual rules depend on the local service.</p><div class="sort-grid">${['🥬 Fruit & vegetable peels','♻ Clean, accepted rigid bottle','▧ Soiled mixed-material wrapper'].map((x,i)=>`<div class="sort-row"><strong>${x}</strong><select aria-label="Pathway for ${esc(x)}" data-sort="${i}"><option value="">Choose a pathway</option>${['Organic processing partner','Accepted-material recycling partner','Locally designated residual route'].map((v,j)=>`<option value="${j}" ${state.sortValues[i]===String(j)?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div>${button('Check My Pathways','check-sort')}<div aria-live="polite">${state.sortChecked?'<div class="feedback">✓ All three pathways connect. Clean accepted materials and organic scraps need separate, viable downstream routes. Mixed or contaminated packaging may need a different route; always check local rules.</div>':sortError?'<div class="feedback error">Try again: food scraps → organics; an accepted clean bottle → recycling partner; this soiled mixed wrapper → the designated residual route.</div>':''}</div>${state.sortChecked?quiz(stopQuestions.sorting,'sorting'):''}`}<div class="actions">${button(state[kind]?'Location Complete · Back to Map':'Complete This Stop',`complete-${kind}`,!(isMarket?state.seen.length===3:state.sortChecked)||state.answers[kind]!==stopQuestions[kind].correct)}</div></section><aside class="activity-aside"><div class="lesson-visual ${isMarket?'':'sort'}"></div><div class="journal-aside"><div class="atlas-row">${owl()}<div><div class="section-label">Atlas’s field note</div><p class="atlas-message">${isMarket?'The best waste is the waste we never create.':'A bin is a beginning, not the whole system.'}</p></div></div><p style="margin-top:20px">${isMarket?'Prevention means avoiding waste before it exists. Collection, recycling, composting, and disposal manage it after it is created. Both behavior and infrastructure shape the outcome.':'Think in connections: clear instructions → participation → separate collection → appropriate processing. If one link breaks, even carefully sorted material may not reach its intended destination.'}</p><span class="badge green">${isMarket?'Waste prevention':'Systems thinking'}</span></div></aside></div></main>`}
function assessment(){const score=[0,1,2].filter(i=>state.assessment[i]===questions[i].correct).length;return `<main id="main" class="paper-main fade-in"><button class="back" data-action="map">← City map</button>${heading('Pause. Connect. Reflect.','What have you discovered?','Three questions to connect your field observations. Missed one? You can always try again.','Both locations explored')}${guidePanel('assessment')}<div class="score-card"><div><strong>${score} / 3</strong><span> &nbsp; ideas connected</span></div><span>✓ Neighborhood Market &nbsp; ✓ Sorting Station</span></div><div class="split"><div class="assessment-grid">${questions.map((q,i)=>`<div class="paper-card"><div class="section-label">Field question 0${i+1}</div>${quiz(q,i,true)}</div>`).join('')}<div class="actions">${button('Enter the Solutions Laboratory','lab',score<3)}</div></div><aside class="journal-aside" style="align-self:start"><div class="atlas-row">${owl()}<h3>Ideas become<br>possibilities.</h3></div><p style="margin-top:22px">Look for the connection between what people do, how a system works, and how we know an improvement is helping.</p>${skills()}<p style="margin-top:20px;font-size:10px">This is an informal learning reflection. It does not award accredited achievement or certification.</p></aside></div></main>`}
const fields=['What problem did you identify?','What is your proposed solution?','Who would participate?','What resources would be needed?','What challenges could arise?','How would you measure success?'];
const sample=['Food scraps and other materials can be mixed at the market, making separate processing difficult.','Pilot food-scrap separation with ten market vendors for four weeks, coordinating with an authorized collection and processing partner.','Ten consenting vendors, market coordinators, collection workers, and a receiving organic-processing partner.','Clearly labeled containers, a simple training session, protective equipment, an agreed pickup schedule, and a weighing scale.','Contamination, irregular pickup, odors, worker safety, and a processing partner that cannot accept the material.','Record a baseline, then track weekly vendor participation, kilograms accepted by the processing partner, contamination, and missed pickups for four weeks.'];
function lab(){return `<main id="main" class="paper-main fade-in"><button class="back" data-action="assessment">← Review your discoveries</button>${heading('The solutions laboratory','Your ideas belong in the world.','You’ve investigated two connected parts of a waste-management system. What practical improvement would you test?','Guided demo feedback')}${guidePanel('lab')}<div class="split" style="grid-template-columns:1.5fr .7fr"><section><div class="paper-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:23px"><span class="section-label" style="margin:0">My pilot project</span><button class="inline-link" data-action="sample">Use a sample proposal</button></div><form id="project-form"><div class="lab-grid">${fields.map((f,i)=>`<div class="lab-field"><label for="project-${i}"><span class="field-number">0${i+1}</span>${f}</label><textarea id="project-${i}" data-project="${i}" maxlength="2000" required placeholder="${['Describe the issue you observed…','Start small. What could you test?','Think about everyone in the system…','People, materials, time, and partners…','What might make this difficult?','A number, a timeframe, a baseline…'][i]}">${esc(state.project[i])}</textarea></div>`).join('')}</div><div class="actions"><button class="primary" type="submit">Save My Project <span class="arrow">↗</span></button><span class="hint">Drafts save as you write.</span></div><p id="project-error" class="form-error"></p></form></div>${state.projectSaved?projectFeedback():''}</section><aside class="journal-aside" style="align-self:start"><div class="atlas-row">${owl()}<h3>Small.<br>Practical.<br>Testable.</h3></div><p style="margin-top:25px">A thoughtful pilot has a clear group, an agreed pathway for materials, and a way to measure progress.</p><p>Your proposal is a student idea, not an implemented or approved real-world project. Consult local partners before trying it.</p><span class="badge">Project planning</span></aside></div></main>`}
function projectFeedback(){const hasMeasure=/\d|weekly|baseline|week|month|kilogram|kg|percent|participation/i.test(state.project[5]);return `<div id="project-feedback" class="paper-card" style="margin-top:20px"><div class="section-label">Saved · Guided demo feedback</div><h3>A promising starting point.</h3><div class="feedback"><strong>A strength:</strong> ${hasMeasure?'Your success section includes a measurable or time-based element, which can make a pilot easier to evaluate.':'You’ve described a problem, a response, and the people needed to work on it.'}</div><p class="hint"><strong>A question to investigate:</strong> Who will confirm that the collection partner and receiving facility can consistently accept your separated material?</p><p class="hint"><strong>A realistic next step:</strong> ${hasMeasure?'Discuss the proposed route with a qualified local partner and agree on a baseline, safety process, and tracking sheet.':'Add a timeframe, baseline, and one countable indicator, then discuss feasibility with a qualified local partner.'}</p><div class="actions">${button('Discover Supporting Research','research')}</div></div>`}
function researchPage(){return `<main id="main" class="paper-main fade-in"><button class="back" data-action="lab">← My project</button>${heading('Follow the evidence','Curiosity meets research.','Find sources to question, compare, and build on. Research discovery works independently of Atlas.','Keenable · Research discovery')}<div class="split"><section class="paper-card"><div class="research-tabs"><button data-category="research" class="${research.category==='research'?'active':''}">Research & evidence</button><button data-category="opportunities" class="${research.category==='opportunities'?'active':''}">Institutions & opportunities</button></div><form id="research-form" class="search-row"><input id="research-query" aria-label="Research search query" value="${esc(research.query)}" maxlength="350" required><button class="primary" ${research.status==='loading'?'disabled':''}>${research.status==='loading'?'Searching…':'Search'} ↗</button></form><div class="suggestions">${['Waste separation research','Urban recycling systems','Educational sustainability initiatives'].map(s=>`<button data-search="${s}">${s}</button>`).join('')}</div>${research.category==='opportunities'?'<div class="feedback">Discovery leads only. Verify eligibility, deadlines, program status, and availability directly with each institution.</div>':''}<div id="research-results" aria-live="polite">${research.status==='loading'?'<div class="empty-state loading-dots">Following the research trail</div>':research.status==='error'?`<div class="feedback error">${esc(research.error)} You can retry or explore the curated sample resources below.</div>${sampleResources()}`:research.status==='success'?`<p class="hint">Live Keenable results · ${esc(research.mode)} · Source text may contain unverified claims. Compare evidence and dates.</p>${research.results.length?research.results.map(r=>`<article class="resource"><span class="badge">${research.category==='research'?'Research discovery':'Opportunity discovery'}</span><h3>${esc(r.title)}</h3><span class="source-url">${esc(safeUrl(r.url))}</span><p>${esc((r.snippet||r.description||'Open the source to review its evidence and publication date.').slice(0,600))}</p><a href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join(''):'<div class="empty-state">No results for this search. Try a more specific question.</div>'}`:`<p class="hint">Search securely through the server-side Keenable API. With no key, the public tier is used; service limits may apply.</p>${sampleResources()}`}</div></section><aside class="journal-aside" style="align-self:start"><div class="atlas-row">${owl()}<h3>A source is<br>a starting point.</h3></div><p style="margin-top:22px">Who wrote it? When? What evidence supports it? Does it apply to this place and this project?</p><p>Our market and sorting station are fictional learning environments. Search results are external sources, not proof that your proposal will work.</p><div class="actions">${button('Reflect & Finish Chapter','finish')}</div><p class="hint">Your saved proposal and discoveries will be gathered into downloadable field notes.</p></aside></div></main>`}
function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function sampleResources(){return `<div class="resource"><span class="badge">Curated sample · General background</span><h3>Goal 12: Responsible consumption and production</h3><p>The UN’s official goal page gives a starting point for understanding the wider challenge. This is a general resource, not Addis Ababa field evidence or a live search result.</p><a href="https://sdgs.un.org/goals/goal12" target="_blank" rel="noopener noreferrer">Open UN source ↗</a></div><p class="hint">Connection: server-side KEENABLE_API_KEY is optional for the public tier. Set it in the deployment’s secret environment to use the authenticated tier. Keys are never sent to the browser.</p>`}
function completion(){return `<main id="main" class="paper-main fade-in"><section class="completion-hero"><div class="medal">✺</div><div class="eyebrow" style="justify-content:center">Chapter one · Field notes complete</div><h1>Look how far curiosity took you.</h1><p>${esc(state.name)} &nbsp; · &nbsp; Addis Ababa, Ethiopia &nbsp; · &nbsp; SDG 12</p><div class="completion-avatar">${avatar()}</div><span class="badge green">A city of possibilities</span></section><div class="completion-columns"><section class="paper-card"><div class="section-label">Your journey</div><h3>Two places. Connected ideas.</h3><ul class="note-list"><li>✓ Neighborhood Market — waste generation & prevention</li><li>✓ Community Sorting Station — collection & processing</li><li>✓ Knowledge reflection — 3 of 3 ideas connected</li><li>✓ A practical pilot proposal saved</li></ul>${skills()}<p class="hint">Informal educational demo · No accredited certificate</p></section><section class="paper-card"><div class="section-label">Your proposal · Student idea</div><h3>A first step toward change.</h3><p class="project-summary">${esc(state.project[1])}</p><p class="hint"><strong>Measuring success:</strong> ${esc(state.project[5])}</p></section></div><div class="actions" style="justify-content:center;margin-top:35px">${button('Download My Field Notes','download')}${button('Review My Journey','map',false,'secondary')}${button('Return to World Globe','home',false,'secondary')}</div></main>`}
function render(){const homeMode=screen==='home';const views={home,profile,adventures,planner,travel,map,market:()=>activity('market'),sorting:()=>activity('sorting'),assessment,lab,research:researchPage,completion};$('#app').innerHTML=`<div class="app-shell ${homeMode?'hero-shell':''}">${header(homeMode)}${(views[screen]||home)()}${!['home','map','travel'].includes(screen)?footer():''}</div>${!['home','profile','travel','map'].includes(screen)?`<button class="floating-atlas" data-action="atlas">${owl()}Ask Atlas</button>`:''}${modal?renderModal():''}`;bind();Earth.start($('.earth-canvas'),screen==='travel');}
function go(to){clearTimeout(travelTimer);modal=null;screen=to;state.screen=to;save();render();window.scrollTo(0,0);if(to==='travel')travelTimer=setTimeout(()=>go('map'),matchMedia('(prefers-reduced-motion: reduce)').matches?1400:5500)}
function start(){if(!state.name)return go('profile');let to=state.screen;if(['home','profile','travel','completion'].includes(to))to=state.completed?'completion':countStops()===2?(assessmentPassed()?(state.projectSaved?'research':'lab'):'assessment'):'map';go(to||'planner')}
function renderModal(){return `<div class="modal-backdrop" data-backdrop="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${modal==='atlas'?'Ask Atlas':'Explorer journal'}" tabindex="-1"><button class="modal-close" data-action="close" aria-label="Close dialog">×</button>${modal==='atlas'?chatPanel():modal==='journal'?`<div class="eyebrow">${esc(state.name)||'Your'} explorer’s journal</div><h2>Little discoveries.<br>Lasting ideas.</h2><p>${countStops()}/2 locations complete · ${[0,1,2].filter(i=>state.assessment[i]===questions[i].correct).length}/3 knowledge questions connected</p><ul class="note-list">${state.seen.map(i=>`<li><strong>${objects[i].title}:</strong> ${objects[i].body}</li>`).join('')||'<li>Your field notes will appear as you explore.</li>'}${state.sortChecked?'<li>Sorting pathways connect organics, accepted recyclables, and residuals to their appropriate destinations.</li>':''}</ul>${state.projectSaved?`<h3>My project</h3><p style="margin-top:12px">${esc(state.project[1])}</p>`:''}<div class="actions">${button('Download Field Notes','download')}</div>`:modal==='scene'?`<h2>Another dimension.</h2><div class="scene-fallback"><span class="scene-icon">⌂</span><p>No licensed 3D scene has been supplied.</p><p>The illustrated adventure remains fully playable.</p><code>Optional asset: /public/assets/addis-scene.glb</code></div><p style="margin-top:20px">The optional GLB viewer activates when a suitably licensed asset is uploaded and the app is rebuilt. It supports orbit controls and independent loading failure handling.</p>`:modal==='about'?`<h2>The living explorer’s atlas.</h2><p>Original illustrations combine antique cartography, painterly exploration, and parchment dialogue inspired by your references. The city is a fictional educational scene, not a precise geographic map.</p><p>Learning content teaches general waste-system concepts and makes no claims about current 2026 infrastructure in Addis Ababa. Proposals are hypothetical student work.</p><div class="about-grid"><div><strong>Keenable</strong>Server-side research discovery, with a public tier and honest error fallback.</div><div><strong>Snowflake</strong>Curriculum schema included. This chapter currently loads local demo data.</div><div><strong>Epic Fab</strong>Optional licensed environment asset. No asset supplied.</div></div><p style="margin-top:18px">Atlas: Keenable research sources. Progress: this browser’s local storage. No student account required.</p>`:typeof modal==='object'?`<div class="eyebrow">Future chapters</div><h2>${goals.find(g=>g.n===modal.goal)?.title||'A growing world'}</h2><p>This adventure is coming in a future release. Chapter 01 in Addis Ababa is ready to explore today.</p>${button('Explore SDG 12','planner')}`:''}</section></div>`}
function openModal(value){modal=value;render();setTimeout(()=>$('.modal')?.focus(),0);if(value==='scene')import('/scene.js').then(m=>m.mountScene($('.scene-fallback'))).catch(()=>{});}

async function runSearch(query){if(research.status==='loading')return;research.query=query;research.status='loading';render();try{const r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:query+(research.category==='opportunities'?' institutions programs educational sustainability opportunities':''),category:research.category}),signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Research service unavailable.');research.results=data.results;state.sources=[...new Map([...state.sources,...data.results.map(r=>({title:r.title,url:r.url}))].map(r=>[r.url,r])).values()].slice(-40);save();research.mode=data.mode;research.status='success';}catch(e){research.status='error';research.error=e.name==='TimeoutError'?'The research service took too long.':e.message.includes('JSON')?'The research endpoint is unavailable in this static preview.':e.message;}render();}
function notes(){return `# EDUTOPIA — My Field Notes\n\nExplorer: ${state.name||'Explorer'}\nAvatar: ${avatars[state.avatar].name}\nAdventure: A city of possibilities\nLocation: Addis Ababa, Ethiopia (fictionalized learning environments)\nGoal: SDG 12 — Responsible Consumption and Production\n\n## Locations explored\n- Neighborhood Market: ${state.market?'Complete':'Not complete'}\n- Community Sorting Station: ${state.sorting?'Complete':'Not complete'}\n\n## My written field notes\n${Object.entries(state.reflections).map(([stop,note])=>stop+': '+note).join('\n')}\n\n## My observations\n${state.seen.map(i=>`- ${objects[i].title}: ${objects[i].body}`).join('\n')}\n\n## Knowledge reflection\n${questions.map((q,i)=>`- ${q.q}\n  My answer: ${state.assessment[i]!==undefined?q.options[state.assessment[i]]:'Not answered'}\n  ${q.explanation}`).join('\n')}\n\n## My pilot proposal (student idea)\n${fields.map((f,i)=>`### ${f}\n${state.project[i]||'Not yet written'}`).join('\n\n')}\n\n## Skills practiced\nSystems thinking; environmental literacy; critical thinking; research; project planning.\n\n## Research sources discovered\n${state.sources.map(r=>`- ${r.title}: ${r.url}`).join('\n')||'No live sources saved in this session. General background: https://sdgs.un.org/goals/goal12'}\n\n## Context\nThis is an informal educational simulation, not an accredited assessment. The market and sorting station are fictional; proposals are hypothetical. Curriculum: local demo data. Atlas responses are labeled by source. External opportunities require direct verification.\n`;}
function download(){const blob=new Blob([notes()],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`EDUTOPIA-${(state.name||'Explorer').replace(/[^a-zA-Z0-9_-]/g,'-')}-field-notes.md`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your field notes are ready to download.');}
function action(a){switch(a){case'home':return go('home');case'start':return start();case'profile':return go('profile');case'save-profile':{const name=$('#explorer-name').value.trim();if(!name){$('#name-error').textContent='Give your explorer a name to begin.';$('#explorer-name').focus();return}state.name=name;save();return go('adventures')}case'adventures':return state.name?go('adventures'):go('profile');case'preview':return state.name?go('planner'):go('profile');case'planner':return state.name?go('planner'):go('profile');case'travel':return go('travel');case'map':return go('map');case'journal':return openModal('journal');case'atlas':return openModal('atlas');case'about':return openModal('about');case'scene':return openModal('scene');case'close':modal=null;render();return;case'check-sort':state.sortChecked=state.sortValues.every((v,i)=>v===String(i));sortError=!state.sortChecked;save();render();return;case'complete-market':if(state.seen.length===3&&state.answers.market===1){state.market=true;save();toast('Market discoveries added to your journal.');go('map')}return;case'complete-sorting':if(state.sortChecked&&state.answers.sorting===0){state.sorting=true;save();toast('Sorting station complete. You’ve connected the system.');go('map')}return;case'assessment':return countStops()===2?go('assessment'):toast('Explore both locations first.');case'lab':return assessmentPassed()?go('lab'):toast('Connect all three knowledge questions first.');case'sample':state.project=[...sample];state.projectSaved=false;save();render();toast('Sample loaded. Make it your own before saving.');return;case'research':if(state.projectSaved){state.researchVisited=true;save();go('research')}return;case'finish':if(state.projectSaved&&assessmentPassed()&&countStops()===2){state.completed=true;save();go('completion')}return;case'download':return download();}}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('[data-avatar]').forEach(b=>b.addEventListener('click',()=>{state.name=$('#explorer-name').value;state.avatar=Number(b.dataset.avatar);save();render()}));$('#explorer-name')?.addEventListener('input',e=>{const out=$('#explorer-preview');if(out)out.textContent=e.target.value.trim()||'A curious new explorer'});document.querySelectorAll('[data-goal]').forEach(b=>b.addEventListener('click',()=>Number(b.dataset.goal)===12?go('planner'):openModal({goal:Number(b.dataset.goal)})));document.querySelectorAll('[data-location]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.location,v=$('.map-avatar');if(v){v.style.left=kind==='market'?'29%':'63%';v.style.top=kind==='market'?'44%':'54%'}clearTimeout(travelTimer);travelTimer=setTimeout(()=>go(kind),matchMedia('(prefers-reduced-motion:reduce)').matches?0:1100)}));document.querySelectorAll('[data-object]').forEach(b=>b.addEventListener('click',()=>{observation=Number(b.dataset.object);if(!state.seen.includes(observation))state.seen.push(observation);save();const y=scrollY;render();scrollTo(0,y)}));document.querySelectorAll('[data-quiz]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.quiz;if(b.dataset.assessment)state.assessment[key]=Number(b.dataset.answer);else state.answers[key]=Number(b.dataset.answer);save();const y=scrollY;render();scrollTo(0,y)}));document.querySelectorAll('[data-sort]').forEach(s=>s.addEventListener('change',()=>{state.sortValues[Number(s.dataset.sort)]=s.value;state.sortChecked=false;save();if($('.feedback')){const y=scrollY;render();scrollTo(0,y)}}));document.querySelectorAll('[data-project]').forEach(t=>t.addEventListener('input',()=>{state.project[Number(t.dataset.project)]=t.value;state.projectSaved=false;$('#project-feedback')?.remove();save()}));$('#project-form')?.addEventListener('submit',e=>{e.preventDefault();if(!state.project.every(t=>t.trim().length>=10)){ $('#project-error').textContent='Add at least 10 characters to each section so Atlas has enough to reflect on.';return}state.projectSaved=true;save();render();toast('Your proposal is saved in this browser.');});$('#research-form')?.addEventListener('submit',e=>{e.preventDefault();runSearch($('#research-query').value.trim())});document.querySelectorAll('[data-search]').forEach(b=>b.addEventListener('click',()=>runSearch(b.dataset.search)));document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{if(research.status==='loading')return;research.category=b.dataset.category;research.status='idle';research.results=[];research.query=research.category==='opportunities'?'Ethiopia sustainability education institutions and programs':'Addis Ababa waste separation and collection research';render()}));bindGuide();$('.modal-backdrop')?.addEventListener('click',e=>{if(e.target.dataset.backdrop){modal=null;render()}});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button,.modal input,.modal a[href],.modal select,.modal textarea')].filter(x=>!x.disabled);if(!items.length)return;let first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();

fetch('/api/curriculum').then(r=>r.ok?r.json():Promise.reject()).then(({source,data})=>{curriculumSource=source;curriculumData=data;if(screen==='planner'||screen==='completion')render();}).catch(()=>{});
